def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = sum(1 for x in opp if x == 'D')

    if n >= 5 and opp_d / n > 0.6:
        return 'D'
    if n >= 10 and opp_d / n > 0.8:
        return 'D'

    my_def_indices = [i for i in range(n-1) if my[i] == 'D']
    if len(my_def_indices) >= 2:
        non_punish = sum(1 for i in my_def_indices if opp[i+1] == 'C')
        if non_punish / len(my_def_indices) > 0.5:
            return 'D'

    if n < 3:
        return 'C' if opp[-1] == 'C' else 'D'

    if n == 3:
        if all(x == 'C' for x in opp) and all(x == 'C' for x in my):
            return 'D'

    if n == 4:
        if my[3] == 'D' and opp[3] == 'C':
            return 'C'

    probed = (n >= 5 and my[3] == 'D' and my[4] == 'C')
    if probed:
        if opp[4] == 'C':
            return 'D'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if n >= 2 and my[-2] == 'D' and opp_d / n < 0.5:
            return 'C'
        return 'D'
    else:
        return 'C'
